# /tmp/audit_list_bullets_vs_numbered_fix.py
import sys; sys.path.insert(0, '.')
from phase0_v2.calibration.audit_helpers import measure_fix_errors
from phase0_v2.calibration._shared import load_records
import re

_BULLET_RE = re.compile(r'^-\s', re.MULTILINE)
_NUMBERED_RE = re.compile(r'^(?:\*\*)?\d+[.)]\s', re.MULTILINE)

def _all_bullets_are_sub_items_fixed(text):
    seen_numbered = False
    has_bullets = False
    for line in text.splitlines():
        if _NUMBERED_RE.match(line):
            seen_numbered = True
        elif _BULLET_RE.match(line):
            has_bullets = True
            if not seen_numbered or not line[0].isspace():
                return False
    return has_bullets

def _count_top_level_bullets(text):
    return len(_BULLET_RE.findall(text))

def _count_top_level_numbered(text):
    return len(_NUMBERED_RE.findall(text))

def is_bullets_fixed(r):
    bullets = _count_top_level_bullets(r)
    numbered = _count_top_level_numbered(r)
    if bullets > 0 and bullets > numbered:
        if numbered > 0 and _all_bullets_are_sub_items_fixed(r):
            return False
        return True
    return False

def is_numbered_fixed(r):
    bullets = _count_top_level_bullets(r)
    numbered = _count_top_level_numbered(r)
    if numbered > 0 and numbered > bullets:
        return True
    if numbered > 0 and bullets > numbered and _all_bullets_are_sub_items_fixed(r):
        return True
    return False

records = load_records('phase0_v2/data/results/google_gemma-3-27b-it_results.jsonl')
fix = measure_fix_errors(records, 'list_bullets_vs_numbered', is_bullets_fixed, is_numbered_fixed)
print(f'old: {fix["old_labels"]}')
print(f'new: {fix["new_labels"]}')
print(f'error_pct: {fix["error_pct"]:.2f}%  (neither={fix["new_neither"]}, both={fix["new_both"]})')
print(f'changed: {fix["changed"]} labels')
